<script>
import axios from "axios";
import FormMixin from "./../../mixins/Common/Form.vue";
export default {
  mixins: [FormMixin],
  name: "AssistantGerant",

  data() {
    return {
      question: "",
      historique: [],
      loading: false,
      erreur: null,
      suggestions: [
        this.$vuetify.lang.t("$vuetify.ai_assistant.ca_day"),
        this.$vuetify.lang.t("$vuetify.ai_assistant.this_month"),
        this.$vuetify.lang.t("$vuetify.ai_assistant.bill_pending"),
        this.$vuetify.lang.t("$vuetify.ai_assistant.avg"),
        this.$vuetify.lang.t("$vuetify.ai_assistant.mon_tuesday"),
      ],
    };
  },

  methods: {
    poserQuestion(texte) {
      this.question = texte;
      this.envoyerQuestion();
    },
    forceRefresh() {
      this.dialog.show = false;
      this.items = [];
      this.active = false;
    },
    async envoyerQuestion() {
      if (!this.question.trim() || this.loading) return;
      if (this.question.length > 500) {
        this.erreur = "Question trop longue (max 500 caractères).";
        return;
      }

      const questionEnvoyee = this.question.trim();
      const heure = new Date().toLocaleTimeString("fr-FR", {
        hour: "2-digit",
        minute: "2-digit",
      });

      this.question = "";
      this.erreur = null;
      this.loading = true;

      try {
        const token = localStorage.getItem("token");
        const { data } = await axios.post(
          "/bills/assistant",
          { question: questionEnvoyee },
          {
            headers: token ? { Authorization: `Bearer ${token}` } : {},
          }
        );

        this.historique.push({
          question: questionEnvoyee,
          reponse: data.reponse,
          heure,
        });

        this.$nextTick(() => {
          const el = this.$refs.chatBody;
          if (el) el.scrollTop = el.scrollHeight;
        });
      } catch (error) {
        this.erreur =
          error.response?.data?.error ||
          "Impossible de contacter l'assistant. Vérifiez votre connexion.";
      } finally {
        this.loading = false;
      }
    },

    formatReponse(texte) {
      if (!texte) return "";
      return texte
        .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>")
        .replace(/\*(.*?)\*/g, "<em>$1</em>")
        .replace(/\n\n/g, "</p><p>")
        .replace(/\n/g, "<br>");
    },
  },
};
</script>

